/* Buildless prototype. All simulation stays local; no hardware or AI connection. */
(()=>{'use strict';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d');
const foods=[{id:'tomato',name:'番茄',dish:'浓缩火焰番茄',color:'#c8624a'},{id:'potato',name:'咖啡土豆',dish:'焦糖咖啡土豆',color:'#caa169'},{id:'mushroom',name:'蘑菇',dish:'榛香蘑菇煲',color:'#9a8c9b'}];
const stations=[{id:'tomato',x:60,y:70,w:130,h:92,label:'番茄箱',type:'source',food:0},{id:'potato',x:205,y:70,w:130,h:92,label:'土豆箱',type:'source',food:1},{id:'mushroom',x:350,y:70,w:130,h:92,label:'蘑菇箱',type:'source',food:2},{id:'chop',x:550,y:70,w:180,h:92,label:'切菜台',type:'chop'},{id:'stove',x:860,y:125,w:160,h:118,label:'炒菜台',type:'stove'},{id:'plates',x:860,y:440,w:160,h:104,label:'盘子台',type:'plates'},{id:'serve',x:60,y:450,w:190,h:98,label:'出餐口',type:'serve'},{id:'trash',x:60,y:290,w:95,h:88,label:'垃圾桶',type:'trash'},{id:'counter',x:430,y:305,w:245,h:100,label:'临时置物台',type:'counter'}];
let state='intro',player={x:290,y:265,held:null,face:0},keys={},orders=[],score=0,served=0,missed=0,combo=0,time=180,elapsed=0,seq=0,delivery=0,path=[],target=null,autoWork=null,last=0,toastTime=0,particles=[],sound=true,audio=null;
function beep(freq=450){if(!sound)return;try{audio ||= new (window.AudioContext||window.webkitAudioContext)();const o=audio.createOscillator(),g=audio.createGain();o.connect(g);g.connect(audio.destination);o.frequency.value=freq;g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.1);o.start();o.stop(audio.currentTime+.1)}catch{}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');toastTime=2.8}
function addOrder(){const f=foods[seq%3];orders.push({id:++seq,food:f.id,left:seq<=3?65+(seq-1)*25:80,max:seq<=3?65+(seq-1)*25:80});}
function reset(){player={x:290,y:265,held:null,face:0};stations.forEach(s=>s.item=null);score=served=missed=combo=elapsed=seq=delivery=0;time=180;orders=[];for(let i=0;i<3;i++)addOrder();keys={};path=[];target=autoWork=null;particles=[];challenge.reset();renderUI();}
function begin(){reset();state='playing';$('#overlay').classList.add('hidden');$('#pause').textContent='暂停';canvas.focus();toast('豆盒开店！先取菜，靠近工作台进入近景挑战');beep(650);}
function modal(k,t,p,b){$('#modalKicker').textContent=k;$('#modalTitle').textContent=t;$('#modalText').innerHTML=p;$('#start').textContent=b;$('#overlay').classList.remove('hidden');keys={};}
function finish(){state='ended';modal('SHIFT COMPLETE','打烊，辛苦了！',`本局得分 <b>${score}</b> · 成功出餐 <b>${served}</b> 单 · 超时 <b>${missed}</b> 单<br>${served>=5?'豆盒米其林，给你摘星！':served>=2?'后厨节奏已掌握，再挑战一次吧。':'先熟悉路线，每一份菜都要切、炒、装盘。'}`,'再开一家店 →');}
function pause(){if(state==='playing'){state='paused';modal('TAKE A BREATH','后厨暂停中','灶火和订单倒计时都已暂停。<br>准备好后，继续你的厨房接力。','继续营业 →');$('#pause').textContent='继续';}else if(state==='paused'){state='playing';$('#overlay').classList.add('hidden');$('#pause').textContent='暂停';canvas.focus();}}
$('#start').onclick=()=>state==='paused'?pause():begin();$('#pause').onclick=pause;$('#restart').onclick=()=>{state='confirm';modal('NEW SHIFT','重新开店？','开始新一局会清空本局成绩和台面。','确认重新开始 →');};$('#sound').onclick=()=>{sound=!sound;$('#sound').textContent='音效 '+(sound?'开':'关');};
document.querySelectorAll('[data-practice]').forEach(b=>b.onclick=()=>{begin();const mode=b.dataset.practice,item={food:'tomato',state:mode==='chop'?'raw':mode==='cook'?'chopped':'plated',progress:0,heat:0};if(mode==='carry'){player.held=item;player.x=830;player.y=570;}else{const s=stations.find(s=>s.type===mode.replace('cook','stove'));s.item=item;player.x=s.x+s.w/2;player.y=s.y+s.h+45;}challenge.start(mode,item);renderUI();});
function food(id){return foods.find(f=>f.id===id)}
function name(i){return i?(i.state==='raw'?'生':i.state==='chopped'?'切好':i.state==='cooked'?'炒熟':i.state==='burnt'?'糊掉':'已装盘')+'的'+food(i.food).name:'两手空空'}
function nearest(){let best=null,dist=Infinity;for(const s of stations){let dx=player.x-Math.max(s.x,Math.min(player.x,s.x+s.w)),dy=player.y-Math.max(s.y,Math.min(player.y,s.y+s.h)),d=Math.hypot(dx,dy);if(d<dist){dist=d;best=s;}}return dist<85?best:null;}
function burst(x,y,color){for(let i=0;i<12;i++)particles.push({x,y,vx:(Math.random()-.5)*130,vy:-Math.random()*100-20,life:1,color});}
function grab(s=nearest()){if(state!=='playing'||challenge.mode)return;if(!s){toast('走近食材箱或工作台再操作');return;}const h=player.held;
if(s.type==='source'){if(h){toast('手里有东西，先放在置物台或丢进垃圾桶');return;}player.held={food:foods[s.food].id,state:'raw',progress:0};toast('拿到'+food(player.held.food).name+'，去切菜台！');beep();}
else if(s.type==='trash'){if(h){player.held=null;toast('已丢弃手中物品');}else toast('先拿起需要丢弃的食材');}
else if(s.type==='plates'){if(h?.state==='cooked'){h.state='plated';challenge.start('carry',h);toast('近景端盘：按住 E 前进，A / D 修正倾斜');beep(700);}else toast(h?'熟菜才能装盘':'拿起炒熟的菜，再来装盘');}
else if(s.type==='serve'){if(h?.state==='plated')toast('停下来，按住 E 平稳出餐');else toast('出餐需要一盘炒好的菜');}
else if(!h&&s.item){if(s.type==='stove'&&s.item.state==='chopped'){toast('还没炒熟，按住 E 颠锅加速');return;}player.held=s.item;s.item=null;autoWork=null;toast('拿起'+name(player.held));beep();}
else if(h&&!s.item){if(s.type==='chop'&&h.state!=='raw'){toast('砧板只接收生食材');return;}if(s.type==='stove'&&h.state!=='chopped'){toast('食材要先切好才能下锅');return;}s.item=h;player.held=null;if(s.type==='stove'){h.progress=0;h.heat=0;challenge.start('cook',h);toast('小幅翻炒按住 E；提示出现时按 F 大幅颠勺');}else if(s.type==='chop'){challenge.start('chop',h);toast('近景切菜：按住 E，或点按砧板');}else toast('暂时放在台面上');beep(350);}
else toast(s.item?'台面已有食材，先空手拿走':'手中没有食材');renderUI();}
function deliver(){let i=orders.findIndex(o=>o.food===player.held.food);if(i<0){toast('没有这道菜的订单，可以先放到置物台');delivery=0;return;}const o=orders.splice(i,1)[0];combo++;let gain=100+Math.floor(o.left)+Math.min(combo-1,5)*15;score+=gain;served++;player.held=null;delivery=0;burst(player.x,player.y,'#e7ae58');toast(`出餐成功！+${gain} 分`);beep(900);addOrder();}
function valid(x,y){if(x<42||x>1058||y<42||y>622)return false;return !stations.some(s=>x>s.x-20&&x<s.x+s.w+20&&y>s.y-20&&y<s.y+s.h+20);}
// Grid navigation keeps click-to-walk routes clear of the central island.
function routeValid(x,y){return valid(x,y)&&!stations.some(s=>x>s.x-27&&x<s.x+s.w+27&&y>s.y-27&&y<s.y+s.h+27);}
function navigate(s){if(challenge.mode)return;const step=25,cols=44,rows=26;const ix=Math.round(player.x/step),iy=Math.round(player.y/step);let goals=[];for(let y=2;y<rows-1;y++)for(let x=2;x<cols-1;x++){let px=x*step,py=y*step,dx=px-Math.max(s.x,Math.min(px,s.x+s.w)),dy=py-Math.max(s.y,Math.min(py,s.y+s.h));if(routeValid(px,py)&&Math.hypot(dx,dy)<62)goals.push([x,y]);}if(!goals.length)return;const goal=new Set(goals.map(g=>g.join(','))),q=[[ix,iy]],seen=new Set([`${ix},${iy}`]),prev=new Map();let found=null;for(let p=0;p<q.length;p++){const [x,y]=q[p],k=`${x},${y}`;if(goal.has(k)){found=k;break;}for(const [dx,dy]of[[1,0],[-1,0],[0,1],[0,-1]]){const nx=x+dx,ny=y+dy,nk=`${nx},${ny}`;if(!seen.has(nk)&&routeValid(nx*step,ny*step)){seen.add(nk);prev.set(nk,k);q.push([nx,ny]);}}}if(!found){toast('这边过不去，换一条路线');return;}path=[];while(found!==`${ix},${iy}`){const [x,y]=found.split(',').map(Number);path.unshift({x:x*step,y:y*step});found=prev.get(found);}target=s;autoWork=null;if(!path.length)arrived(s);}
function pointerPos(e){const r=canvas.getBoundingClientRect();return{x:(e.clientX-r.left)*1100/r.width,y:(e.clientY-r.top)*680/r.height};}
canvas.addEventListener('pointerdown',e=>{if(state!=='playing')return;e.preventDefault();canvas.focus();const {x,y}=pointerPos(e);if(challenge.mode){canvas.setPointerCapture(e.pointerId);challenge.down(x,y);return;}const s=stations.find(s=>x>s.x-15&&x<s.x+s.w+15&&y>s.y-15&&y<s.y+s.h+15);if(s)navigate(s);});
canvas.addEventListener('pointermove',e=>{if(challenge.mode){const {x,y}=pointerPos(e);challenge.move(x,y);}});
for(const ev of ['pointerup','pointercancel','lostpointercapture'])canvas.addEventListener(ev,()=>challenge.up());
function arrived(s){target=null;if(s.type==='serve'&&player.held?.state==='plated'){autoWork=s;return;}if(s.type==='chop'&&s.item?.state==='raw'&&!player.held){challenge.start('chop',s.item);return;}grab(s);if(s.type==='chop'&&s.item?.state==='raw'&&!challenge.mode)challenge.start('chop',s.item);}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();if(k==='escape'){pause();return;}if(state!=='playing')return;keys[k]=true;if(k==='f'&&!e.repeat&&challenge.mode==='cook')challenge.flip();if(k===' '&&!e.repeat){autoWork=null;grab();}if(['w','a','s','d','arrowup','arrowdown','arrowleft','arrowright'].includes(k)){path=[];target=autoWork=null;}});
window.addEventListener('keyup',e=>keys[e.key.toLowerCase()]=false);window.addEventListener('blur',()=>{keys={};challenge.up();if(state==='playing')pause();});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key.toLowerCase();b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[k]=true;if(k==='f')challenge.flip();path=[];target=autoWork=null;});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keys[k]=false);});$('#touchGrab').onclick=()=>grab();
function update(dt){if(state!=='playing')return;elapsed+=dt;time=Math.max(0,time-dt);if(!time){finish();return;}toastTime-=dt;if(toastTime<0)$('#toast').classList.remove('show');for(let i=orders.length-1;i>=0;i--){orders[i].left-=dt;if(orders[i].left<=0){orders.splice(i,1);missed++;combo=0;score=Math.max(0,score-30);addOrder();toast('订单超时，扣除 30 分！');}}
if(challenge.mode){challenge.update(dt,keys);if(challenge.mode==='carry'){const p=challenge.data.progress;player.x=830-p*525;player.y=570;}renderUI();return;}
let dx=Number(keys.d||keys.arrowright||false)-Number(keys.a||keys.arrowleft||false),dy=Number(keys.s||keys.arrowdown||false)-Number(keys.w||keys.arrowup||false);if(path.length){const p=path[0],d=Math.hypot(p.x-player.x,p.y-player.y);if(d<6){path.shift();if(!path.length&&target)arrived(target);}else{dx=(p.x-player.x)/d;dy=(p.y-player.y)/d;}}
const len=Math.hypot(dx,dy),moving=len>0,speed=keys.shift?290:215;if(len){dx/=len;dy/=len;if(valid(player.x+dx*speed*dt,player.y))player.x+=dx*speed*dt;if(valid(player.x,player.y+dy*speed*dt))player.y+=dy*speed*dt;player.face=Math.atan2(dy,dx);}
const s=nearest(),work=(keys.e||autoWork===s)&&!moving;if(autoWork&&autoWork!==s)autoWork=null;
if(s?.type==='chop'&&s.item?.state==='raw'&&!player.held&&work)challenge.start('chop',s.item);
const stove=stations.find(s=>s.type==='stove');if(stove.item){const i=stove.item;if(i.state==='chopped'&&s===stove&&work)challenge.start('cook',i);else if(i.state==='cooked'){i.heat+=dt;if(i.heat>20){i.state='burnt';combo=0;toast('糊锅了！拿去垃圾桶，重新做一份');beep(180);}}}
if(s?.type==='serve'&&player.held?.state==='plated'&&work){delivery+=dt;if(delivery>=1.3){deliver();autoWork=null;}}else delivery=0;
particles.forEach(p=>{p.life-=dt;p.x+=p.vx*dt;p.y+=p.vy*dt;p.vy+=150*dt;});particles=particles.filter(p=>p.life>0);renderUI();}
function renderUI(){renderChallengeUI();$('#score').textContent=String(score).padStart(3,'0');$('#served').textContent=served;$('#time').textContent=`${String(Math.floor(Math.ceil(time)/60)).padStart(2,'0')}:${String(Math.ceil(time)%60).padStart(2,'0')}`;$('.clock').classList.toggle('urgent',time<30);$('#combo').textContent=combo>1?`${combo} 连续出餐 · 奖励加成`:'把热菜端到顾客面前';$('#orders').innerHTML=orders.map(o=>`<div class="order ${o.left<15?'urgent':''}"><div class="order-top"><span>订单 ${String(o.id).padStart(2,'0')}</span><span>${Math.ceil(o.left)}s</span></div><h3>${food(o.food).dish}</h3><div class="order-bottom"><span>${food(o.food).name} · 切 / 炒 / 装盘</span><span>+100</span></div><div class="track"><i style="width:${o.left/o.max*100}%"></i></div></div>`).join('');$('#hand').textContent=name(player.held);let stage=0,h=player.held,chop=stations.find(s=>s.type==='chop'),stove=stations.find(s=>s.type==='stove');if(h)stage={raw:1,chopped:2,cooked:3,plated:4,burnt:0}[h.state];else if(chop.item)stage=chop.item.state==='raw'?1:2;else if(stove.item)stage=stove.item.state==='cooked'?3:2;document.querySelectorAll('.step').forEach(e=>e.classList.toggle('active',Number(e.dataset.step)===stage));$('#hint').textContent=['先按订单去食材箱取菜','切菜台自动拉近，按住 E 完成十刀','小幅翻炒按 E，指定时机按 F 大幅翻面','拿起熟菜，去右下方盘子台装盘','近景端盘：E 前进，A / D 保持平衡'][stage];}
function rect(x,y,w,h,r,fill,stroke){ctx.beginPath();ctx.roundRect(x,y,w,h,r);ctx.fillStyle=fill;ctx.fill();if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=2;ctx.stroke();}}
function text(t,x,y,size=16,color='#493321',align='center'){ctx.font=`500 ${size}px "Noto Sans SC",sans-serif`;ctx.fillStyle=color;ctx.textAlign=align;ctx.textBaseline='middle';ctx.fillText(t,x,y);}
function ellipse(x,y,rx,ry,c){ctx.beginPath();ctx.ellipse(x,y,rx,ry,0,0,Math.PI*2);ctx.fillStyle=c;ctx.fill();}
function foodDraw(i,x,y,scale=1){if(!i)return;const f=food(i.food);ctx.save();ctx.translate(x,y);ctx.scale(scale,scale);if(i.state==='plated'){ellipse(0,3,30,18,'#a5ad9b');ellipse(0,0,30,18,'#f7f2df');ellipse(0,0,23,12,'#dfdfcb');}if(i.state==='burnt'){ellipse(0,0,20,12,'#474637');text('糊',0,0,14,'#eee0c7');}else if(i.state==='raw'){if(i.food==='tomato'){ellipse(0,0,17,15,f.color);text('✦',0,-13,19,'#536a45');}else if(i.food==='potato'){ctx.rotate(-.3);ellipse(0,0,20,13,f.color);ellipse(-8,-3,2,2,'#96754b');ellipse(6,4,2,2,'#96754b');}else{ellipse(0,7,5,12,'#e9ddc9');ellipse(0,-3,21,12,f.color);}}else{for(let j=0;j<6;j++){const a=j*2.4;rect(Math.cos(a)*12-5,Math.sin(a)*7-4,10,8,2,i.state==='cooked'?'#b77c42':f.color);}}ctx.restore();}
function bar(x,y,w,p,color='#708958'){rect(x,y,w,6,3,'#d6d6bf');rect(x,y,w*Math.max(0,Math.min(1,p)),6,3,color);}
function drawWorld(){ctx.clearRect(0,0,1100,680);rect(0,0,1100,680,0,'#322219');rect(16,18,1068,625,52,'#b9986a','#70523c');rect(32,40,1036,586,40,'#734a30','#e6cf9d');
ctx.strokeStyle='#93613c';ctx.lineWidth=2;for(let j=0;j<20;j++){ctx.beginPath();for(let x=35;x<1070;x+=15){const y=59+j*29+Math.sin(x*.012+elapsed*.8+j)*7;x===35?ctx.moveTo(x,y):ctx.lineTo(x,y);}ctx.stroke();}
for(let j=0;j<42;j++){const x=45+(j*193+elapsed*8)%1010,y=58+(j*113)%546;drawBean(x,y,11+j%4*3,j*.7);}
rect(365,15,370,33,9,'#38291f');text('BEAN HOPPER · 咖啡机豆盒后厨',550,32,13,'#ecd6ae');text('备 菜 浮 台',350,207,14,'#d1b182');text('烘 焙 炒 台',920,292,14,'#d1b182');text('出 餐 栈 桥',190,580,14,'#e2c59b');
if(path.length){ctx.setLineDash([4,8]);ctx.strokeStyle='#9aaf80';ctx.beginPath();ctx.moveTo(player.x,player.y);path.forEach(p=>ctx.lineTo(p.x,p.y));ctx.stroke();ctx.setLineDash([]);}
const near=nearest();for(const s of stations){let color=s.type==='stove'?'#8f7359':s.type==='serve'?'#ad8d55':s.type==='trash'?'#80705c':'#aa8a64';rect(s.x+4,s.y+9,s.w,s.h,7,'#533c2a');rect(s.x,s.y,s.w,s.h,7,color,near===s?'#b46d46':'#76543a');rect(s.x+7,s.y+7,s.w-14,s.h-27,4,s.type==='source'?'#d0ad79':'#dfc49a');text(s.label,s.x+s.w/2,s.y+s.h-11,13,'#493321');
if(s.type==='source'){const f=foods[s.food];foodDraw({food:f.id,state:'raw'},s.x+s.w/2,s.y+35);text('∞',s.x+s.w-16,s.y+16,13,'#6e7c58');}
if(s.type==='chop'){rect(s.x+32,s.y+16,s.w-64,43,5,'#bc996a','#9d7c50');ctx.save();ctx.translate(s.x+s.w-42,s.y+38);ctx.rotate(s.item?.state==='raw'&&(keys.e||autoWork===s)?Math.sin(elapsed*25)*.3:-.4);rect(-5,-26,10,30,2,'#eeeadc');rect(-4,4,8,16,2,'#657263');ctx.restore();}
if(s.type==='stove'){for(let j=0;j<2;j++){ellipse(s.x+46+j*65,s.y+39,27,24,'#69715e');ellipse(s.x+46+j*65,s.y+39,20,18,s.item&&j===0?'#c47d43':'#949b84');}rect(s.x+22,s.y+42,10,42,4,'#56614e');if(s.item){ellipse(s.x+46,s.y+35,25,20,'#414c3e');ellipse(s.x+46,s.y+32,21,16,'#697657');}}
if(s.type==='plates'){for(let j=3;j>=0;j--){ellipse(s.x+55,s.y+39+j*4,29,17,'#a8ae99');ellipse(s.x+55,s.y+36+j*4,29,17,'#f5efdb');}text('装盘',s.x+113,s.y+39,13,'#78846c');}
if(s.type==='serve'){rect(s.x+15,s.y+17,s.w-30,39,4,'#526d57');text('↑ 交单',s.x+s.w/2,s.y+36,18,'#eee7d2');}
if(s.type==='trash'){ellipse(s.x+47,s.y+35,25,20,'#66755d');text('×',s.x+47,s.y+34,27,'#cad1b9');}
if(s.type==='counter'){text('可暂存一份食材',s.x+s.w/2,s.y+35,13,'#8a8b74');}
if(s.item){let px=s.type==='stove'?s.x+46:s.x+s.w/2,py=s.y+35;foodDraw(s.item,px,py);if(s.item.state==='raw'&&s.type==='chop')bar(s.x+20,s.y-14,s.w-40,s.item.progress);if(s.type==='stove'){if(s.item.state==='chopped'){bar(s.x+10,s.y-14,s.w-20,s.item.progress);text('烹饪中',s.x+s.w/2,s.y-30,12);}if(s.item.state==='cooked'){bar(s.x+10,s.y-14,s.w-20,1-s.item.heat/12,s.item.heat>8?'#c75b3f':'#708958');text(s.item.heat>8?'要糊啦！快取走':'已熟 · 可以装盘',s.x+s.w/2,s.y-30,12,s.item.heat>8?'#b74631':'#526d57');}}}
if(near===s&&state==='playing'){let label=s.type==='source'?'空格取菜':s.type==='chop'?(s.item?.state==='raw'?'按住 E 切菜':'空格拿 / 放'):s.type==='stove'?'空格拿放 · E 颠锅':s.type==='plates'?'空格装盘':s.type==='serve'?'按住 E 平稳出餐':s.type==='trash'?'空格丢弃':'空格拿 / 放';rect(s.x+s.w/2-91,s.y+s.h+9,182,25,5,'#39291fee');text(label,s.x+s.w/2,s.y+s.h+21,11,'#fff2d4');}}
// Simple paper-cut chef, with a carried item visible above the hat.
const bob=(keys.w||keys.a||keys.s||keys.d||path.length)?Math.sin(elapsed*17)*2:0;ellipse(player.x,player.y+17,23,10,'#49321e66');ctx.save();ctx.translate(player.x,player.y+bob);rect(-14,2,11,18,4,'#4e6155');rect(3,2,11,18,4,'#4e6155');ellipse(0,-1,23,23,'#c76746');rect(-14,-4,28,22,7,'#f4e8cf');ellipse(0,-17,17,16,'#d6ad83');ellipse(-13,-29,13,11,'#f7f3e4');ellipse(0,-34,15,13,'#f7f3e4');ellipse(13,-29,13,11,'#f7f3e4');rect(-16,-28,32,11,4,'#eee9d9');ellipse(-5,-15,1.5,2,'#4a5342');ellipse(5,-15,1.5,2,'#4a5342');ctx.restore();if(player.held){rect(player.x-31,player.y-89,62,42,8,'#f4efde','#aab29b');foodDraw(player.held,player.x,player.y-69,.8);}if(delivery>0)bar(player.x-40,player.y+36,80,delivery/1.3);particles.forEach(p=>{ctx.globalAlpha=p.life;rect(p.x,p.y,5,5,1,p.color);ctx.globalAlpha=1;});
}

function drawBean(x,y,size,angle){ctx.save();ctx.translate(x,y);ctx.rotate(angle);ellipse(0,0,size*1.4,size,'#4d2f21');ctx.strokeStyle='#b08252';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(-size*.7,size*.3);ctx.bezierCurveTo(-size*.1,-size*.7,size*.1,size*.7,size*.7,-size*.3);ctx.stroke();ctx.restore();}
function draw(){ctx.save();if(challenge.mode){const z=1+Math.min(.75,challenge.age*1.5),s=challenge.mode==='chop'?stations.find(s=>s.type==='chop'):challenge.mode==='cook'?stations.find(s=>s.type==='stove'):player;const x=s.w?s.x+s.w/2:s.x,y=s.h?s.y+s.h/2:s.y;ctx.translate(550,340);ctx.scale(z,z);ctx.translate(-x,-y);}drawWorld();ctx.restore();challenge.draw(ctx,foodDraw);}
function renderChallengeUI(){const mode=challenge.mode,panel=$('#challengePanel');panel.hidden=!mode;$('.canvas-wrap').classList.toggle('focus-active',!!mode);$('#focusControls').hidden=!mode;$('#flipButton').hidden=mode!=='cook';$('#balanceLeft').hidden=$('#balanceRight').hidden=mode!=='carry';$('#workButton').textContent=mode==='carry'?'按住前进 E':mode==='cook'?'小幅翻炒 E':'按住切菜 E';if(!mode)return;const d=challenge.data;$('#focusTitle').textContent=mode==='chop'?'刀 · 十刀备菜':mode==='cook'?(d.window>0?'现在！大幅颠勺翻面':'锅 · 小幅翻炒'):'盘 · 流动咖啡平衡';$('#focusStatus').textContent=mode==='chop'?`${d.hits}/10 刀 · 按住 E 或点按砧板`:mode==='cook'?`翻面 ${d.flips}/2 · ${d.window>0?'按 F / 向上大幅滑动':'按住 E / 小幅拖动锅'} · 焦糊 ${Math.round(d.scorch)}%`:`路程 ${Math.round(d.progress*100)}% · 完整度 ${Math.max(0,Math.round(d.integrity))}% · E 前进，A/D 修正`;}
const challenge=new window.CoffeeChallenge(result=>{path=[];target=autoWork=null;keys={};if(result.mode==='chop'){const s=stations.find(s=>s.type==='chop');if(s.item){s.item.state='chopped';s.item.progress=1;}toast('切好啦！空格或点击拿起，去炒菜台');beep(700);}else if(result.mode==='cook'){const s=stations.find(s=>s.type==='stove');if(s.item){s.item.state=result.ok?'cooked':'burnt';s.item.progress=1;s.item.heat=0;}toast(result.ok?'两次翻面完成！拿起熟菜去装盘':'火候失控，糊锅了！拿去垃圾桶重新来');beep(result.ok?800:180);}else{player.x=305;player.y=500;if(result.ok){if(player.held)deliver();}else{player.held=null;score=Math.max(0,score-25);combo=0;toast('盘子失衡，菜洒了！扣 25 分，重新取菜');beep(180);}}renderUI();});

function tick(t){let dt=Math.min((t-last)/1000,.04);last=t;update(dt);draw();requestAnimationFrame(tick);}reset();requestAnimationFrame(tick);
})();
